{"Channel": {"name": "develop-davidgarcia-SummarizeForce", "channelID": "ch-force-6723be"}, "Message": {"User": {"userId": "slack_admin_bot", "timestamp": "2026-11-10T04:02:00", "text": "@eid_136119e9 joined develop-davidgarcia-SummarizeForce.", "utterranceID": "20261110-26-9648f"}, "Reactions": []}, "ThreadReplies": [], "id": "20261110-26-9648f"}
