{"Channel": {"name": "planning-SummarizeForce", "channelID": "ch-zeaix-5f5953"}, "Message": {"User": {"userId": "eid_95f6d01c", "timestamp": "2026-10-23T19:43:00", "text": "Hi team, I've shared the <https://sf-internal.slack.com/archives/docs/summarizeforce_system_design_document|System Design Document> for SummarizeForce. Let's discuss any feedback or suggestions you might have. Looking forward to your thoughts! 😊", "utterranceID": "20261023-0-a580c"}, "Reactions": []}, "ThreadReplies": [], "id": "20261023-0-a580c"}
