{"Channel": {"name": "bug-georgebrown-SearchFlow", "channelID": "ch-hflow-8b2bf1"}, "Message": {"User": {"userId": "eid_de315467", "timestamp": "2026-09-12T20:50:00", "text": "Great news, @eid_e01a396c! Could you explain what the root cause was?", "utterranceID": "20260912-1-d8976"}, "Reactions": []}, "ThreadReplies": [], "id": "20260912-1-d8976"}
