{"Channel": {"name": "planning-pAIX", "channelID": "ch--paix-374b62"}, "Message": {"User": {"userId": "eid_469598db", "timestamp": "2026-07-10T09:48:00", "text": "Hi team, one of the common issues reported for pAIX is the limited integration options with popular CRM systems. This was reported by Customer ID: CUST-0114.", "utterranceID": "20260704-0-fa01d"}, "Reactions": []}, "ThreadReplies": [], "id": "20260704-0-fa01d"}
