{"Channel": {"name": "bug-bobbrown-CollaborateForce", "channelID": "ch-force-a5e3e1"}, "Message": {"User": {"userId": "eid_d3a4fc8f", "timestamp": "2027-02-24T17:38:00", "text": "Hi team, several customers are reporting issues with CollaborateForce that need our attention. Let's go through them one by one. 😊", "utterranceID": "20270224-0-df913"}, "Reactions": []}, "ThreadReplies": [], "id": "20270224-0-df913"}
