{"Channel": {"name": "bug-alicemartinez-ConnectForce", "channelID": "ch-force-c583cf"}, "Message": {"User": {"userId": "eid_294ba09d", "timestamp": "2026-07-09T10:44:00", "text": "Hi team, several customers are reporting issues with our ConnectForce product. Let's go through them and assign tasks. 😊", "utterranceID": "20260709-0-ead71"}, "Reactions": []}, "ThreadReplies": [], "id": "20260709-0-ead71"}
