{"Channel": {"name": "planning-extAIX", "channelID": "ch-xtaix-274901"}, "Message": {"User": {"userId": "eid_435d10af", "timestamp": "2026-09-02T10:42:00", "text": "The previous team might not have set up a comprehensive feedback mechanism. We should look into that.", "utterranceID": "20260828-7-5d921"}, "Reactions": []}, "ThreadReplies": [], "id": "20260828-7-5d921"}
